import{_ as a,o,c as r,a2 as l}from"./chunks/framework.DpXDHk3d.js";const g=JSON.parse('{"title":"15.2 理论考试技巧总结","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/15-chapter-15-li-lun-kao-shi-ying-shi-ji-qiao/15-2-li-lun-kao-shi-ji-qiao-zong-jie.md","filePath":"electrician/low-voltage-electrician/15-chapter-15-li-lun-kao-shi-ying-shi-ji-qiao/15-2-li-lun-kao-shi-ji-qiao-zong-jie.md","lastUpdated":1795661954000}'),i={name:"electrician/low-voltage-electrician/15-chapter-15-li-lun-kao-shi-ying-shi-ji-qiao/15-2-li-lun-kao-shi-ji-qiao-zong-jie.md"};function d(e,t,n,h,s,u){return o(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="_15-2-理论考试技巧总结" tabindex="-1">15.2 理论考试技巧总结 <a class="header-anchor" href="#_15-2-理论考试技巧总结" aria-label="Permalink to &quot;15.2 理论考试技巧总结&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>这一节把<strong>上机怎么答</strong>讲透:判断题怎么找破绽、单选题怎么排除、时间怎么分配、检查时改不改答案。考试形式和题型结构见 <a href="/some-docs/electrician/low-voltage-electrician/15-chapter-15-li-lun-kao-shi-ying-shi-ji-qiao/15-1-li-lun-kao-shi-jie-shao.html">15.1 理论考试介绍</a>。</p><h2 id="一、开考前先看清规则" tabindex="-1">一、开考前先看清规则 <a class="header-anchor" href="#一、开考前先看清规则" aria-label="Permalink to &quot;一、开考前先看清规则&quot;">​</a></h2><p>坐下来别急着答题,先确认三件事:</p><ol><li><strong>题量和总分</strong>:一共多少题、每题多少分、及格线多少;</li><li><strong>能不能回看和修改</strong>:多数机考允许前后翻题,少数按顺序作答;</li><li><strong>交卷规则</strong>:时间到是否自动交卷、未答题怎么计分。</li></ol><blockquote><p>💡 如果系统允许跳题,先把整套题快速翻一遍,心里对难度分布有底。</p></blockquote><h2 id="二、判断题的五种抓手" tabindex="-1">二、判断题的五种抓手 <a class="header-anchor" href="#二、判断题的五种抓手" aria-label="Permalink to &quot;二、判断题的五种抓手&quot;">​</a></h2><p>判断题只有&quot;对/错&quot;两个结果,破绽往往就藏在表述方式里。</p><h3 id="_1-抓绝对词" tabindex="-1">1. 抓绝对词 <a class="header-anchor" href="#_1-抓绝对词" aria-label="Permalink to &quot;1. 抓绝对词&quot;">​</a></h3><p>看到&quot;<strong>一定、必须、肯定、任何、全部、绝对、都、只有、完全</strong>&quot;这类词,先打个问号——这类表述大多数是<strong>错</strong>的。</p><p>但要注意:凡是<strong>规范里的硬性要求</strong>,绝对化表述反而是对的,例如:</p><ul><li>&quot;检修前必须验电&quot; —— 对;</li><li>&quot;接地线必须先接接地端&quot; —— 对;</li><li>&quot;任何情况下都允许带电作业&quot; —— 错(规范禁止)。</li></ul><p><strong>判断方法</strong>:绝对词 + 违反安全常识/规范 → 错;绝对词 + 本身就是强制规定 → 对。</p><h3 id="_2-抓安全红线" tabindex="-1">2. 抓安全红线 <a class="header-anchor" href="#_2-抓安全红线" aria-label="Permalink to &quot;2. 抓安全红线&quot;">​</a></h3><p>出现下面这些内容,只要陈述成&quot;可以/允许/没关系&quot;,基本就是错:</p><ul><li>带电作业不采取防护;</li><li>徒手拉扯触电者;</li><li>约时停送电;</li><li>保护接地与保护接零混用;</li><li>用铜丝、铁丝代替熔体;</li><li>漏电保护器动作后不查原因直接合闸;</li><li>用水或泡沫扑救带电火灾。</li></ul><h3 id="_3-抓顺序词" tabindex="-1">3. 抓顺序词 <a class="header-anchor" href="#_3-抓顺序词" aria-label="Permalink to &quot;3. 抓顺序词&quot;">​</a></h3><p>涉及&quot;先……后……&quot;的题,背熟这几组固定顺序:</p><table tabindex="0"><thead><tr><th>场景</th><th>正确顺序</th></tr></thead><tbody><tr><td>停电检修</td><td>停电 → 验电 → 装设接地线 → 悬挂标示牌和装设遮栏</td></tr><tr><td>装设接地线</td><td>先接<strong>接地端</strong>,后接<strong>导体端</strong></td></tr><tr><td>拆除接地线</td><td>先拆<strong>导体端</strong>,后拆<strong>接地端</strong>(与装设相反)</td></tr><tr><td>触电急救</td><td>先<strong>脱离电源</strong>,再<strong>就地抢救</strong></td></tr><tr><td>电气火灾</td><td>先<strong>切断电源</strong>,再<strong>灭火</strong></td></tr></tbody></table><h3 id="_4-抓数值" tabindex="-1">4. 抓数值 <a class="header-anchor" href="#_4-抓数值" aria-label="Permalink to &quot;4. 抓数值&quot;">​</a></h3><p>判断题里的数值往往只改一个数字,记熟下面这张表就能秒判:</p><table tabindex="0"><thead><tr><th>项目</th><th>数值</th></tr></thead><tbody><tr><td>高低压分界</td><td>1 kV(1000 V)</td></tr><tr><td>安全电压等级</td><td>42 / 36 / 24 / 12 / 6 V</td></tr><tr><td>感知 / 摆脱 / 危险电流</td><td>1 / 10 / 50 mA</td></tr><tr><td>漏电保护器动作值</td><td>30 mA,≤0.1 s</td></tr><tr><td>保护接地 / 重复接地电阻</td><td>≤4 Ω / ≤10 Ω</td></tr><tr><td>低压设备绝缘电阻</td><td>≥0.5 MΩ</td></tr><tr><td>证书有效期 / 复审周期</td><td>6 年 / 3 年</td></tr><tr><td>心肺复苏按压与吹气比</td><td>30 : 2</td></tr><tr><td>按压频率 / 深度</td><td>100~120 次/分 / 5~6 cm</td></tr></tbody></table><h3 id="_5-抓主体" tabindex="-1">5. 抓主体 <a class="header-anchor" href="#_5-抓主体" aria-label="Permalink to &quot;5. 抓主体&quot;">​</a></h3><p>看清&quot;<strong>谁</strong>负责、<strong>谁</strong>发证、<strong>向谁</strong>申请&quot;:</p><ul><li>特种作业操作证由<strong>应急管理部门</strong>考核发证;</li><li>生产经营单位<strong>主要负责人</strong>对本单位安全生产工作全面负责;</li><li>从业人员有权<strong>拒绝</strong>违章指挥和强令冒险作业。</li></ul><h2 id="三、单选题的四种解法" tabindex="-1">三、单选题的四种解法 <a class="header-anchor" href="#三、单选题的四种解法" aria-label="Permalink to &quot;三、单选题的四种解法&quot;">​</a></h2><h3 id="_1-直接选" tabindex="-1">1. 直接选 <a class="header-anchor" href="#_1-直接选" aria-label="Permalink to &quot;1. 直接选&quot;">​</a></h3><p>纯记忆题(数值、单位、符号、颜色),背过就能直接选,不要犹豫。</p><h3 id="_2-排除法" tabindex="-1">2. 排除法 <a class="header-anchor" href="#_2-排除法" aria-label="Permalink to &quot;2. 排除法&quot;">​</a></h3><p>先排除明显错误的选项,通常能排除两个:</p><ul><li>违反安全常识的;</li><li>数值明显离谱的(如安全电压写 220V);</li><li>主体或对象错位的(问&quot;发证机关&quot;却写培训机构)。</li></ul><h3 id="_3-对比法" tabindex="-1">3. 对比法 <a class="header-anchor" href="#_3-对比法" aria-label="Permalink to &quot;3. 对比法&quot;">​</a></h3><p>两个选项只差一两个字时,差异就是考点:</p><ul><li>&quot;线电压 / 相电压&quot;;</li><li>&quot;保护接地 / 保护接零&quot;;</li><li>&quot;过载 / 短路&quot;;</li><li>&quot;电流表串联 / 电压表并联&quot;;</li><li>&quot;先接接地端 / 先接导体端&quot;。</li></ul><h3 id="_4-常识与安全原则代入" tabindex="-1">4. 常识与安全原则代入 <a class="header-anchor" href="#_4-常识与安全原则代入" aria-label="Permalink to &quot;4. 常识与安全原则代入&quot;">​</a></h3><p>实在不会时,选<strong>更安全、更保守、更符合规程</strong>的那个:能断电就不带电,能防护就不裸露,能停机就不凑合。</p><h2 id="四、数值题的考场技巧" tabindex="-1">四、数值题的考场技巧 <a class="header-anchor" href="#四、数值题的考场技巧" aria-label="Permalink to &quot;四、数值题的考场技巧&quot;">​</a></h2><ul><li><strong>看单位</strong>:mA 和 A、Ω 和 kΩ、V 和 kV,单位错一位答案就错;</li><li><strong>看线/相</strong>:380V 是线电压,220V 是相电压;</li><li><strong>看有效值/最大值</strong>:220V 是有效值,最大值约 311V;</li><li><strong>看数量级</strong>:人体电流是 mA 级,不是 A 级;</li><li><strong>不要现场推导</strong>:背熟的数值直接选,推导容易在紧张时出错。</li></ul><h2 id="五、时间分配" tabindex="-1">五、时间分配 <a class="header-anchor" href="#五、时间分配" aria-label="Permalink to &quot;五、时间分配&quot;">​</a></h2><p>以&quot;100 题 / 60 分钟&quot;为例:</p><table tabindex="0"><thead><tr><th>阶段</th><th>用时</th><th>任务</th></tr></thead><tbody><tr><td>第一遍</td><td>35~40 分钟</td><td>先判断题、再单选题,会的直接过</td></tr><tr><td>标记</td><td>全程</td><td>不确定的题做标记,不纠缠</td></tr><tr><td>第二遍</td><td>10~15 分钟</td><td>集中处理标记题</td></tr><tr><td>最后</td><td>3~5 分钟</td><td>检查未答题、漏选、错行</td></tr></tbody></table><blockquote><p>⚠️ 单题超过 1 分钟就跳过做标记。机考最怕的不是不会,而是<strong>后面会做的题没时间做</strong>。</p></blockquote><h2 id="六、遇到不会的题怎么办" tabindex="-1">六、遇到不会的题怎么办 <a class="header-anchor" href="#六、遇到不会的题怎么办" aria-label="Permalink to &quot;六、遇到不会的题怎么办&quot;">​</a></h2><ol><li><strong>绝不空题</strong>:机考一般不倒扣分,空着等于白丢分;</li><li><strong>排除到两个再选</strong>:二选一的命中率远高于四选一;</li><li>**优先选&quot;安全侧&quot;**的答案;</li><li><strong>相信第一直觉</strong>:没有确凿理由不要反复改;</li><li><strong>先做标记往后走</strong>,回头再看时心态放松,反而容易想起来。</li></ol><h2 id="七、检查与修改的原则" tabindex="-1">七、检查与修改的原则 <a class="header-anchor" href="#七、检查与修改的原则" aria-label="Permalink to &quot;七、检查与修改的原则&quot;">​</a></h2><ul><li><strong>只改&quot;确定错&quot;的题</strong>,拿不准的不改;</li><li>重点检查三类题:带&quot;不属于/错误的是&quot;的否定题、有数值和单位的题、多选题;</li><li>检查答案是否&quot;错行&quot;——机考点选误触很常见;</li><li>交卷前确认系统提示的&quot;未答题数&quot;为 0。</li></ul><h2 id="八、常见失分原因" tabindex="-1">八、常见失分原因 <a class="header-anchor" href="#八、常见失分原因" aria-label="Permalink to &quot;八、常见失分原因&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原因</th><th>典型表现</th><th>对策</th></tr></thead><tbody><tr><td>看错题干</td><td>&quot;不属于&quot;&quot;错误的是&quot;看成肯定问法</td><td>读题先圈关键词</td></tr><tr><td>数值混淆</td><td>4Ω 和 10Ω、36V 和 12V 记混</td><td>背 15.3 的数字速记表</td></tr><tr><td>概念混用</td><td>保护接零说成保护接地</td><td>用&quot;系统类型&quot;判断</td></tr><tr><td>顺序记反</td><td>接地线先接导体端</td><td>记&quot;先接地,后接设备&quot;</td></tr><tr><td>时间不够</td><td>前面纠结太久</td><td>1 分钟原则,果断跳过</td></tr><tr><td>改错答案</td><td>反复改,把对的改成错的</td><td>无确凿理由不改</td></tr></tbody></table><h2 id="九、复习策略与考前一周安排" tabindex="-1">九、复习策略与考前一周安排 <a class="header-anchor" href="#九、复习策略与考前一周安排" aria-label="Permalink to &quot;九、复习策略与考前一周安排&quot;">​</a></h2><h3 id="_1-总体策略" tabindex="-1">1. 总体策略 <a class="header-anchor" href="#_1-总体策略" aria-label="Permalink to &quot;1. 总体策略&quot;">​</a></h3><ol><li><strong>先过考点提示</strong>:把各章的 ✅ 必背点背熟;</li><li><strong>边学边练</strong>:每节的自测练习 + 15.4、15.5 两套题,做完立刻对答案;</li><li><strong>错题归因</strong>:把错题按&quot;数值记不住 / 概念混淆 / 粗心&quot;分类,针对性补;</li><li><strong>考前两天</strong>:重点再过安全技术、急救、法规三个板块,不碰新内容。</li></ol><h3 id="_2-考前一周安排" tabindex="-1">2. 考前一周安排 <a class="header-anchor" href="#_2-考前一周安排" aria-label="Permalink to &quot;2. 考前一周安排&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时间</th><th>任务</th></tr></thead><tbody><tr><td>考前 7 天</td><td>通读 15.3,把易错点过一遍</td></tr><tr><td>考前 5 天</td><td>做 15.4 选择题,错题归因</td></tr><tr><td>考前 3 天</td><td>做 15.5 判断题,错题归因</td></tr><tr><td>考前 2 天</td><td>只看错题和数字速记表</td></tr><tr><td>考前 1 天</td><td>过一遍法规数字、安全数值、急救要点,早点休息</td></tr><tr><td>考试当天</td><td>提前到场,带齐证件,不临时抱佛脚看新内容</td></tr></tbody></table><h2 id="十、答题口诀" tabindex="-1">十、答题口诀 <a class="header-anchor" href="#十、答题口诀" aria-label="Permalink to &quot;十、答题口诀&quot;">​</a></h2><ul><li><strong>判断题</strong>:绝对词多思量,安全红线不能放,顺序数值记心上。</li><li><strong>单选题</strong>:先排除、再比较,不会就选最安全。</li><li><strong>时间管理</strong>:一分钟,先跳过;做标记,回头收。</li><li><strong>检查</strong>:只改确定错,不改心里慌。</li></ul><h2 id="十一、考点提示" tabindex="-1">十一、考点提示 <a class="header-anchor" href="#十一、考点提示" aria-label="Permalink to &quot;十一、考点提示&quot;">​</a></h2><ul><li>✅ 判断题抓五样:绝对词、安全红线、顺序、数值、主体;</li><li>✅ 单选题四解法:直接选、排除、对比、安全原则;</li><li>✅ 时间分配:第一遍求稳,第二遍攻标记题;</li><li>✅ 不空题、不纠缠、不乱改;</li><li>⚠️ 否定式题干(&quot;不属于&quot;&quot;错误的是&quot;)是失分重灾区,读题先圈关键词。</li></ul><h2 id="十二、本节小结" tabindex="-1">十二、本节小结 <a class="header-anchor" href="#十二、本节小结" aria-label="Permalink to &quot;十二、本节小结&quot;">​</a></h2><ul><li>先看清规则(题量、及格线、能否回看),再开始答题。</li><li>判断题靠&quot;绝对词 + 安全红线 + 顺序 + 数值 + 主体&quot;五个抓手。</li><li>单选题靠排除、对比和安全原则,数值题靠背,不靠现场推导。</li><li>时间上执行&quot;1 分钟原则&quot;,不空题,检查时只改确定错的。</li><li>考前一周按&quot;通读 → 刷题 → 归因 → 只看错题&quot;的节奏走。</li></ul><h2 id="十三、自测练习" tabindex="-1">十三、自测练习 <a class="header-anchor" href="#十三、自测练习" aria-label="Permalink to &quot;十三、自测练习&quot;">​</a></h2><ol><li>(判断)判断题中出现&quot;任何情况下都可以带电作业&quot;,该说法是正确的。( )</li><li>(单选)装设接地线的正确顺序是( )。 A. 先接导体端,后接接地端　B. 先接接地端,后接导体端　C. 两端同时接　D. 顺序无所谓</li><li>(单选)机考中遇到不会的单选题,较好的做法是( )。 A. 空着不选　B. 排除明显错误项后选一个最安全的　C. 随便点一个　D. 反复修改直到交卷</li><li>(判断)检查时只要拿不准,就应该把答案改掉。( )</li><li>(单选)以 100 题、60 分钟为例,第一遍答题的合理用时是( )。 A. 10 分钟　B. 20 分钟　C. 35~40 分钟　D. 55 分钟</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>×</strong>。带电作业有严格限制,不存在&quot;任何情况下都可以&quot;。</li><li><strong>B</strong>。装设接地线必须先接接地端、后接导体端,拆除时相反。</li><li><strong>B</strong>。不空题,用排除法并结合安全原则选择。</li><li><strong>×</strong>。只改确定错的题,拿不准的不改。</li><li><strong>C</strong>。第一遍用 35~40 分钟,留出复查和处理标记题的时间。</li></ol></details>',63)])])}const c=a(i,[["render",d]]);export{g as __pageData,c as default};
